:root{
  color-scheme: dark;
  --ff-display:"Public Sans",system-ui,sans-serif; --ff-body:"Public Sans",system-ui,sans-serif; --ff-mono:"Courier Prime",ui-monospace,monospace;
  --canvas:#14211B; --surface-1:#1B2B24; --surface-2:#243830; --surface-sunken:#0F1A15;
  --line:#34493F; --line-input:#6F867A;
  --ink:#EEF2EC; --ink-muted:#A9B8AE;
  --accent:#F4F1E8; --accent-ink:#14211B; --focus:#F4F1E8;
  --sheet:#FBFAF5; --sheet-ink:#17181A;
  --data-fails:#F0624D; --data-holds:#7FAEFF;
  --danger:#F0624D; --success:#7FAEFF; --warning:#E9B84A;
  --r-sm:2px; --r-md:4px; --r-lg:8px;
  --ease-out:cubic-bezier(.23,1,.32,1); --ease-in-out:cubic-bezier(.77,0,.175,1);
  --dur-press:120ms; --dur-hover:150ms; --dur-line:350ms; --dur-turn:600ms;
  --pad:24px; --panel:420px;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html,body{margin:0;height:100%}
body{background:var(--canvas);color:var(--ink);font:400 15px/1.45 var(--ff-body);display:grid;grid-template-rows:52px minmax(0,1fr) auto;min-height:100vh;height:100vh;overflow:hidden}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
button{font:inherit;color:inherit}
a{color:var(--ink);text-underline-offset:2px}

.bar{display:flex;align-items:center;gap:20px;padding:0 var(--pad);border-bottom:1px solid var(--line);background:var(--canvas)}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none}
.word{font:800 20px/1 var(--ff-display);letter-spacing:-.03em}
.descriptor{margin:0;color:var(--ink-muted);font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tabs{margin-left:auto;display:flex;border:1px solid var(--line-input);border-radius:var(--r-md);overflow:hidden}
.tabs button{background:none;border:0;padding:6px 14px;cursor:pointer}
.tabs button[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);font-weight:600}

.main{display:grid;grid-template-columns:minmax(760px,1fr) var(--panel);gap:var(--pad);padding:16px var(--pad);min-height:0}
.stage{position:relative;min-height:0;background:var(--surface-sunken);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
.stage::before{content:"";position:absolute;inset:12px;border:1px solid var(--line);border-radius:8px;pointer-events:none}
.viewport{position:absolute;inset:0;perspective:1800px}
.lean{position:absolute;inset:0;transform-style:preserve-3d;will-change:transform}
.pose{position:absolute;left:0;top:0;width:0;height:0;transform-origin:0 0;transform-style:preserve-3d;will-change:transform}
.paper,.stack,.sheet,.marks{position:absolute;left:calc(var(--w) / -2);top:calc(var(--h) / -2);width:var(--w);height:var(--h)}
.paper{transform-style:preserve-3d}
.paper>.stack,.paper>.sheet{left:0;top:0}   /* inside the paper, which is already centred: otherwise the sheet sits half a sheet off the marks */
.stack i.under{background:#000;border:0;box-shadow:calc(var(--inv,1) * 4px) calc(var(--inv,1) * 8px) calc(var(--inv,1) * 18px) calc(var(--inv,1) * 2px) rgba(0,0,0,.85)}
.stack{transform-style:preserve-3d}
.stack i{position:absolute;inset:0;background:#c9c6b8;border-bottom:1px solid #8d8a7d;border-right:1px solid #8d8a7d}
.sheet{background:var(--sheet);color:var(--sheet-ink)}
.sheet img{display:block;width:100%;height:100%;user-select:none;-webkit-user-drag:none}
.far{position:absolute;left:0;right:0;top:0;height:3.5%;background:#000;opacity:.07;pointer-events:none}
.bands{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.marks{overflow:visible;transform:translateZ(calc(var(--inv,1) * .6px))}
.marks rect{fill:transparent;cursor:pointer;stroke:none}
.marks rect:hover{stroke:var(--sheet-ink);stroke-width:calc(2 * var(--u,1))}
.marks rect:focus{outline:none}
.focus-ring{pointer-events:none}
.focus-ring rect{fill:none}
.focus-ring .dark{stroke:var(--sheet-ink);stroke-width:calc(4 * var(--u,1))}
.focus-ring .light{stroke:var(--focus);stroke-width:calc(2 * var(--u,1))}
.bands line{stroke-width:calc(7 * var(--u,1));opacity:.35;fill:none}
.bands line.holds{stroke:var(--data-holds)} .bands line.fails{stroke:var(--data-fails)}
.bands circle{fill:none;stroke-width:calc(3 * var(--u,1))}
.bands circle.holds{stroke:var(--data-holds)} .bands circle.fails{stroke:var(--data-fails)} .bands circle.warn{stroke:var(--warning)}

.ctx{position:absolute;z-index:2;top:17px;left:24px;right:24px;margin:0;font:400 12px/16px var(--ff-body);color:var(--ink-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}
.loupe{position:absolute;z-index:2;top:40px;left:50%;transform:translateX(-50%);width:min(576px,calc(100% - 48px));height:240px;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--sheet-ink);box-shadow:0 1px 1px rgba(0,0,0,.5),0 10px 18px -6px rgba(0,0,0,.55);overflow:hidden}
.loupe.rise{animation:rise 300ms var(--ease-out) both}
@keyframes rise{from{transform:translate(-50%,12px);opacity:0}to{transform:translateX(-50%);opacity:1}}
.lp-view{position:absolute;inset:0;overflow:hidden}
.lp-layer{position:absolute;inset:0;opacity:0;transition:opacity 150ms linear}
.lp-layer.in{opacity:1}
.lp-layer.instant{transition:none}
.lp-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.lp-pan.slide{transition:transform 350ms var(--ease-in-out)}
.lp-pan img{display:block;user-select:none;-webkit-user-drag:none}
.lp-svg{position:absolute;left:0;top:0;overflow:visible}
.lp-svg line{opacity:.26;fill:none}
.lp-svg line.holds{stroke:var(--data-holds)} .lp-svg line.fails{stroke:var(--data-fails)}
.lp-peek rect{fill:none}
.lp-peek .dark{stroke:var(--sheet-ink)} .lp-peek .light{stroke:var(--focus)}
.lp-hit{fill:transparent;cursor:pointer}
.lp-hit:hover{stroke:var(--sheet-ink);stroke-width:1.5}
.lp-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.lp-ring.holds{stroke:var(--data-holds)} .lp-ring.fails{stroke:var(--data-fails)} .lp-ring.warn{stroke:var(--warning)}
.lp-note{position:absolute;left:0;right:0;bottom:0;margin:0;padding:4px 10px;background:var(--sheet);border-top:1px solid #9a9c9e;font-size:12px;line-height:16px;color:#4a4d50}
.leader{position:absolute;inset:0;width:100%;height:100%;z-index:3;pointer-events:none;overflow:visible}
.leader{mix-blend-mode:difference}
.leader line{stroke:var(--ink);stroke-opacity:.6;stroke-width:1.5;stroke-linecap:round}

.notice{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);max-width:420px;background:var(--surface-2);border:1px solid var(--danger);border-radius:var(--r-md);padding:16px 20px;font-size:15px;z-index:4}
.controls{position:absolute;left:24px;bottom:24px;right:24px;z-index:2;display:flex;flex-wrap:wrap;align-items:center;gap:4px 14px}
.controls button:not(.primary){background:none;border:0;padding:4px 0;color:var(--ink);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.controls button:not(.primary):disabled{color:var(--ink-muted);text-decoration:none;cursor:default}
.primary{background:var(--accent);color:var(--accent-ink);border:0;border-radius:var(--r-md);padding:7px 16px;font-weight:600;cursor:pointer;transition:transform var(--dur-press)}
.primary:disabled{cursor:not-allowed}
.primary:not(:disabled):active{transform:translateY(1px)}
.hint{margin:0;color:var(--ink-muted);font-size:12px}
.pageno{color:var(--ink-muted);font-size:13px}

.panel>*{flex:none}
.panel{display:flex;flex-direction:column;gap:8px;min-height:0;overflow-y:auto;padding:0 2px 2px 0}
.tapewrap{filter:drop-shadow(0 1px 0 rgba(0,0,0,.6))}
.tape{background:var(--sheet);color:var(--sheet-ink);padding:6px 14px 12px;font:400 13px/16px var(--ff-mono);min-height:64px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0 18px}
.tape h3{margin:0 0 2px;font:600 13px/16px var(--ff-body);color:#4a4d50}
.tape .sum{min-width:0}
.tape .ln{display:flex;justify-content:space-between;gap:12px;white-space:pre}
.tape .ln span:last-child{text-align:right;font-variant-numeric:tabular-nums}
.tape .ln.pick{cursor:pointer}
.tape .ln.pick:hover{background:#e9e6da}
.tape .ln.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .ln.more{color:#4a4d50}
.tape .res{margin-top:2px;padding:0 8px;font-weight:700;display:inline-block;color:var(--sheet-ink)}
.tape .res.holds{background:var(--data-holds)} .tape .res.fails{background:var(--data-fails)}
.tape .empty{margin:0;color:#4a4d50;font:400 14px var(--ff-body);grid-column:1/-1}
.card{background:var(--surface-1);border:1px solid var(--line);border-radius:var(--r-lg);padding:10px 14px;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:12px;align-items:center}
.card>*{grid-column:1}
.card .eyebrow{margin:0;color:var(--ink-muted);font-size:13px}
.card h2{margin:0;font:600 16px/1.3 var(--ff-body)}
.card .sub{margin:0;color:var(--ink-muted);font-size:13px;line-height:1.3}
.card .big{grid-column:2;grid-row:1/span 3;margin:0;font:700 34px/1 var(--ff-mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.card .status{margin:2px 0 0;font-size:14px}
.card .how{margin:0;color:var(--ink-muted);font-size:12px}
.fails h2{margin:0 0 4px;font:600 13px var(--ff-body);color:var(--ink-muted);letter-spacing:.03em;text-transform:uppercase}
.fails.none h2{text-transform:none;letter-spacing:0;font-size:15px;color:var(--ink)}
.list{list-style:none;margin:0;padding:0;border-top:1px solid var(--line);border-radius:var(--r-sm)}
.list li{display:grid;grid-template-columns:1fr auto;gap:0 12px;padding:6px 10px 6px 12px;border-bottom:1px solid var(--line);border-left:2px solid transparent;cursor:pointer;font-size:14px;line-height:1.35}
.list li .a{font-weight:600} .list li .b{font:400 13px var(--ff-mono);text-align:right;font-variant-numeric:tabular-nums}
.list li .c{grid-column:1/-1;color:var(--ink-muted);font-size:13px}
.list li[aria-selected="true"]{border-left-color:var(--ink);background:var(--surface-1)}
.list li.cur{outline:2px solid var(--focus);outline-offset:-2px}
.list:not(:focus-visible) li.cur{outline:0}
.foot{padding:8px var(--pad) 10px;color:var(--ink-muted);font-size:13px;border-top:1px solid var(--line)}
.foot a{color:var(--ink)}

/* ---- the dock: the primary action and the reason it is blocked (a fixed bar under 900 px) */
.dock{display:contents}
.hint{order:10}
.controls button{min-height:28px}

/* ---- tape lines and the list: buttons and rows that take focus */
.tape button.ln{min-height:24px;align-items:center;width:100%;background:none;border:0;padding:0;margin:0;text-align:left;color:inherit;font:inherit;cursor:pointer}
.tape button.ln:focus-visible{background:var(--sheet-ink);color:var(--sheet);outline:2px solid var(--focus);outline-offset:0}
.list:focus-visible{outline:2px solid var(--focus);outline-offset:2px}

/* ---- states: body[data-state] = loading | error | empty | partial | first-run | ready */
.ghost,.statebox,.flatblock,.skeleton{display:none}
.ghost{position:absolute;inset:0;z-index:1;pointer-events:none;perspective:1800px;overflow:hidden}
.ghost-sheet{position:absolute;left:50%;top:54%;width:min(62%,560px);aspect-ratio:1600/971;background:var(--sheet);opacity:.92;transform:translate(-50%,-50%) rotateX(34deg) rotateZ(-3deg);overflow:hidden}
.scanline{position:absolute;left:0;right:0;top:0;height:3px;background:var(--data-holds);animation:scan 1.6s linear infinite}
@keyframes scan{from{top:-3px}to{top:100%}}
.statebox{position:absolute;left:24px;right:24px;top:24px;z-index:3;margin:0;font:600 15px/1.4 var(--ff-body);text-align:center}
body[data-state="loading"] .ghost{display:block}
body[data-state="loading"] .statebox,body[data-state="first-run"] .statebox{display:block}
body[data-state="loading"] .statebox{top:auto;bottom:80px;font-variant-numeric:tabular-nums}
body[data-state="first-run"] .statebox{top:50%;transform:translateY(-50%);max-width:480px;margin:0 auto}
body[data-state="loading"] .viewport,body[data-state="loading"] .loupe,body[data-state="loading"] .leader,
body[data-state="error"] .viewport,body[data-state="error"] .loupe,body[data-state="error"] .leader,
body[data-state="first-run"] .viewport,body[data-state="first-run"] .loupe,body[data-state="first-run"] .leader,
body[data-state="first-run"] .controls,body[data-state="first-run"] .panel{display:none}
body[data-state="first-run"] .main{grid-template-columns:minmax(0,1fr)}
body[data-state="loading"] .skeleton,body[data-state="error"] .skeleton{display:grid;gap:12px}
body[data-state="loading"] .headline,body[data-state="error"] .headline,body[data-state="loading"] .tapewrap,body[data-state="loading"] .card,body[data-state="loading"] .findings,body[data-state="loading"] .run,body[data-state="loading"] .fails,body[data-state="loading"] .judge,
body[data-state="error"] .tapewrap,body[data-state="error"] .card,body[data-state="error"] .findings,body[data-state="error"] .run,body[data-state="error"] .fails,body[data-state="error"] .judge{display:none}
body[data-state="loading"] .ctx,body[data-state="error"] .ctx,body[data-state="first-run"] .ctx{display:none}
.sk-tape,.sk-card{display:grid;gap:10px;padding:16px 14px;border-radius:var(--r-md)}
.sk-tape{background:var(--surface-2);min-height:150px}
.sk-card{background:var(--surface-1);border:1px solid var(--line);min-height:100px}
.skeleton i{display:block;height:12px;border-radius:var(--r-sm);background:var(--line);animation:pulse 1.6s ease-in-out infinite}
.skeleton i:nth-child(2){width:70%} .skeleton i:nth-child(3){width:85%} .skeleton i:nth-child(4){width:55%}
@keyframes pulse{50%{opacity:.45}}
/* partial: no page image, so the block's own image is shown flat in the sheet zone */
.stage.partial .viewport{display:none}
.stage.partial .flatblock{display:block;position:absolute;z-index:1;left:24px;right:24px;top:calc(40px + 240px + 12px);bottom:84px;overflow:hidden;background:var(--sheet);color:var(--sheet-ink)}
.stage.partial .flatblock p{margin:0;padding:12px;font-size:14px}
.fb-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.fb-pan img{display:block}
.fb-svg{position:absolute;left:0;top:0;overflow:visible}
.fb-svg line{opacity:.26;fill:none} .fb-svg line.holds{stroke:var(--data-holds)} .fb-svg line.fails{stroke:var(--data-fails)}
.fb-hit{fill:transparent;cursor:pointer}
.fb-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.fb-ring.holds{stroke:var(--data-holds)} .fb-ring.fails{stroke:var(--data-fails)}

/* ---- the finding: the card, the tape in two columns, the list, the run numbers, the dialog */
.sr{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.lp-tag{position:absolute;left:0;top:0;z-index:2;pointer-events:none;opacity:0;padding:0 6px;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--sheet-ink);font:400 13px/20px var(--ff-mono);white-space:nowrap;font-variant-numeric:tabular-nums}
.lp-tag.on{opacity:1;transition:opacity 100ms linear}
.lp-tag.slide{transition:transform 350ms var(--ease-in-out),opacity 100ms linear}
.lp-tag.out{z-index:3}
.lp-tag.in-cell::after{content:"";position:absolute;right:-5px;top:9px;width:5px;height:1px;background:var(--sheet-ink)}
.lp-stem{position:absolute;z-index:1;width:1px;margin-left:-.5px;background:var(--sheet-ink);opacity:0;pointer-events:none}
.lp-stem.on{opacity:1}
.lp-ring2{fill:none;stroke:var(--sheet-ink);stroke-dasharray:5 4;pointer-events:none}
.lp-cropbox{display:flex;align-items:center;justify-content:center;background:var(--sheet)}
.lp-crop{display:block;max-width:100%;max-height:100%;object-fit:contain}
.ticks{pointer-events:none}
.ticks .tick circle{fill:none;stroke-width:2}
.ticks .tick.settled circle{stroke:var(--data-fails)} .ticks .tick.open circle{stroke:var(--warning)}

.card.finding{display:block;padding:6px 12px 8px}
.card.finding h2{font-size:15px;line-height:20px;margin:0 0 6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.two-values{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:5px}
.two-values .one{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:0 8px;border:1px solid var(--line-input);border-radius:var(--r-md);padding:3px 10px;min-width:0;background:var(--surface-sunken)}
.two-values .one.scan{border-color:var(--ink)}
.two-values .lab{display:block;flex:none;color:var(--ink-muted);font-size:12px;line-height:16px}
.two-values .fig{display:block;margin-left:auto;font:700 28px/1.1 var(--ff-mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em;overflow-wrap:anywhere}
.card.finding .kind{margin:4px 0 0;font-size:13px;line-height:17px}
.card.finding .kind>*{margin-right:6px}
.card.finding .lab{color:var(--ink-muted);font-size:12px}
.card.finding .kg{font-weight:700;min-width:1ch}
.card.finding .kw{font-weight:600}
.card.finding .kind,.card.finding .sentence{display:inline}
.card.finding .kind::after{content:" "}
.card.finding .sentence{margin:0 0 2px;font-size:13px;line-height:17px}
.decided{font-size:13px;line-height:1.35}
.decided ul{margin:2px 0 0;padding-left:16px}
.card.finding .status{margin:4px 0 0;font-size:13px;line-height:18px;font-weight:600}
.card.finding .status .sg,.st .sg{display:inline-block;min-width:1.2ch;margin-right:4px}
.card.finding .person{margin:0;font-size:12px;line-height:16px;letter-spacing:-.012em;color:var(--ink-muted)}
.card.finding .how{margin:4px 0 0;font-size:13px}
.btns{display:flex;gap:8px;margin-top:6px}
.btns button,.dlg-close{min-height:32px;padding:0 14px;background:none;color:var(--ink);border:1px solid var(--line-input);border-radius:var(--r-md);cursor:pointer}
.btns button:hover,.dlg-close:hover{border-color:var(--ink)}

.tape.two{display:block}
.tape .sum.two h3{margin:0 0 2px}
.tape.two .sum+.sum{margin-top:8px;padding-top:6px;border-top:1px dashed #9a9c9e}
.tape .pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 18px}
.tape .pair.heads h4{margin:0;font:600 12px/16px var(--ff-body);color:#4a4d50}
.tape .pair.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .pair.rule .ln{border:0;margin:0;padding:0}
.tape .ln.diff{background:#f6e3de;box-shadow:inset 3px 0 0 var(--data-fails);padding-left:5px}
.tape .pair>.ln:last-child.diff{background:#dde8fb;box-shadow:inset 3px 0 0 #2f5fb3}
.tape button.ln.diff:focus-visible{background:var(--sheet-ink)}
.tape .res2{margin-top:2px}
.tape .res2 .res{margin-top:0;display:block;white-space:nowrap;font-size:13px}
.tape .others{margin-top:14px;padding-top:8px;border-top:1px dashed #9a9c9e;color:#4a4d50;font-size:13px}
.tape .others>h3{margin:0 0 4px}
.tape .sum.quiet{margin-top:6px;padding:0;border:0;opacity:.92;font-size:13px}
.tape .sum.quiet .ln{font-size:13px;line-height:16px}
.tape .sum.quiet h3{font-size:12px}

.findings h2{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.findings.none h2{position:static;width:auto;height:auto;margin:0 0 2px;overflow:visible;clip:auto}
.run h2,.judge h2{margin:0 0 2px;font:600 13px var(--ff-body);color:var(--ink-muted);letter-spacing:.03em;text-transform:uppercase}
.findings.none h2{text-transform:none;letter-spacing:0;font-size:15px;color:var(--ink)}
.findings.none .filters,.findings.none .showing{display:none}
.filters{margin-bottom:4px;display:flex;gap:6px;overflow-x:auto;scrollbar-width:thin;padding-bottom:2px}
.chips{display:flex;gap:6px;flex:none}
.chip{min-height:28px;padding:2px 10px;white-space:nowrap;background:none;color:var(--ink);border:1px solid var(--line-input);border-radius:14px;cursor:pointer;font-size:13px}
.chip[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent);font-weight:600}
.showing{margin:0 0 4px;font-size:12px;color:var(--ink-muted);min-height:0}
.showing:empty{display:none}
.flist{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}
.flist.virtual{position:relative}
.flist li{font-size:14px;line-height:1.3}
.flist li.grp{display:grid;grid-template-columns:auto auto minmax(0,1fr) auto;gap:0 8px;align-items:baseline;padding:5px 10px 1px 12px;background:var(--surface-1);border-bottom:1px solid var(--line)}
.flist li.grp .kg{font-weight:700;min-width:1.2ch;text-align:center}
.flist li.grp .kw{font-weight:600}
.flist li.grp .rl{color:var(--ink);min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.flist li.grp .pc{color:var(--ink-muted);font-size:13px;white-space:nowrap}
.flist li.fnd{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:0 10px;align-items:center;padding:5px 10px 5px 12px;border-bottom:1px solid var(--line);border-left:2px solid transparent;cursor:pointer;min-height:32px}
.flist li.fnd[aria-selected="true"]{border-left-color:var(--ink);background:var(--surface-2)}
.flist li.fnd.cur{outline:2px solid var(--focus);outline-offset:-2px}
.flist:not(:focus-visible) li.cur{outline:0}
.flist:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.flist .wh{color:var(--ink);font-size:13px}
.flist .vs{font:400 13px var(--ff-mono);font-variant-numeric:tabular-nums;white-space:nowrap}
.flist .ar{margin:0 5px;color:var(--ink-muted)}
.flist .sv{font-weight:700}
.flist .st{font-size:13px;white-space:nowrap;min-width:6.5em}
.flist .st.ok{color:var(--ink)} .flist .st.open{color:var(--warning)}
.flist.virtual li{overflow:hidden}
.flist.virtual li.fnd .wh{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.run{font-size:13px}
.nums{display:grid;grid-template-columns:repeat(auto-fit,minmax(112px,1fr));gap:8px 12px;margin:0}
.nums>div{display:block}
.nums dt{color:var(--ink-muted);font-size:12px;line-height:15px}
.nums dd{margin:0;font:400 15px/18px var(--ff-mono);font-variant-numeric:tabular-nums;display:inline}
.nums dd.unit{font:400 12px var(--ff-body);color:var(--ink-muted);margin-left:4px}
.reader{margin:8px 0 0;color:var(--ink-muted);font-size:13px;line-height:1.4}
.fails summary{cursor:pointer;color:var(--ink-muted);font-size:13px;padding:6px 0;min-height:28px}
.fails summary:hover{color:var(--ink)}
.fails .list{margin-top:4px}
.judge ol{margin:0;padding-left:20px;font-size:14px;color:var(--ink)}
.judge{padding-bottom:4px}

