  .dock{display:flex;flex-direction:row;flex-wrap:wrap;align-items:stretch;gap:2px 8px;position:fixed;z-index:30;left:0;right:0;bottom:0;padding:10px 16px calc(10px + env(safe-area-inset-bottom));background:var(--canvas);border-top:1px solid var(--line)}
  .dock .primary{min-height:48px;flex:1 1 0;order:0}
