.hl-dot{color:var(--line-input)}
.headline .hl-part{white-space:normal}

/* ---- the replay: the caption on the blotter, the wash on the blocks being read, the quiet panel */
.rp-cap{position:absolute;z-index:4;top:12px;left:24px;right:24px;margin:0;font:400 13px/18px var(--ff-body);color:var(--ink);pointer-events:none;min-height:0}
.rp-cap:empty{display:none}
body.replaying .ctx{visibility:hidden}
body.replaying .ticks{display:none}
body.replaying.rp-ticks .ticks{display:inline}
.loupe{transition:opacity 150ms linear}
.loupe.rp-off,.leader.rp-off{opacity:0;pointer-events:none}
.lp-tag.rp-off{opacity:0!important}
.rp{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.rp .wash{fill:var(--data-holds);fill-opacity:.1;transform-box:fill-box;transform-origin:0 50%}
.rp .wash.sweep{animation:sweep 180ms linear both}
.rp .wash.fade{animation:fade 150ms linear both}
.rp .frame{fill:none;stroke:var(--sheet-ink);stroke-width:calc(2 * var(--u,1));stroke-dasharray:calc(8 * var(--u,1)) calc(5 * var(--u,1))}
